class Evaluator:
    def __init__(self, expression: str):
        self.expression = expression
        self.position = 0
        self.current_token = None

    def error(self):
        raise Exception('Invalid syntax')

    def advance(self):
        self.position += 1
        if self.position > len(self.expression) - 1:
            self.current_token = None
            return

        current_char = self.expression[self.position]

        while current_char.isspace():
            self.position += 1
            if self.position > len(self.expression) - 1:
                self.current_token = None
                return
            current_char = self.expression[self.position]

        if current_char.isdigit() or current_char == '.':
            number = ''
            while self.position < len(self.expression) and (self.expression[self.position].isdigit() or self.expression[self.position] == '.'):
                number += self.expression[self.position]
                self.position += 1
            self.current_token = float(number)
            return

        if current_char in '+-*/()':
            self.current_token = current_char
            self.position += 1
            return

        self.current_token = None

    def parse(self):
        self.advance()
        return self.expr()

    def expr(self):
        result = self.term()

        while self.current_token in ('+', '-'):
            token = self.current_token
            self.advance()
            if token == '+':
                result += self.term()
            elif token == '-':
                result -= self.term()

        return result

    def term(self):
        result = self.factor()

        while self.current_token in ('*', '/'):
            token = self.current_token
            self.advance()
            if token == '*':
                result *= self.factor()
            elif token == '/':
                result /= self.factor()

        return result

    def factor(self):
        token = self.current_token
        if isinstance(token, float):
            self.advance()
            return token
        elif token == '(':
            self.advance()
            result = self.expr()
            if self.current_token != ')':
                self.error()
            self.advance()
            return result
        self.error()


